#!/bin/sh
set -eu

# Map the credentials generated by scripts/batc.py into the names used by the
# PJSIP template. Keep the trunk disabled when they are absent so the local
# test PBX still starts without an Exolve account.
: "${BATC_SIP_LOGIN:=${BATC_AGENT_LOGIN:-}}"
# The BATC cabinet shows the employee login as <login>@login.mtt.ru; the SIP
# account uses the local part before the @.
BATC_SIP_LOGIN=${BATC_SIP_LOGIN#sip:}
BATC_SIP_LOGIN=${BATC_SIP_LOGIN%%@*}
: "${BATC_SIP_PASSWORD:=${BATC_AGENT_PASSWORD:-}}"
: "${BATC_SIP_DOMAIN:=sip.exolve.ru}"
: "${BATC_SIP_PORT:=5060}"
: "${BATC_SIP_AUTH_USER:=$BATC_SIP_LOGIN}"
: "${BATC_SIP_FROM_USER:=$BATC_SIP_LOGIN}"
export BATC_SIP_LOGIN BATC_SIP_PASSWORD BATC_SIP_DOMAIN BATC_SIP_PORT BATC_SIP_AUTH_USER BATC_SIP_FROM_USER

if [ -n "$BATC_SIP_LOGIN" ] && [ -n "$BATC_SIP_PASSWORD" ]; then
    envsubst '${BATC_SIP_DOMAIN} ${BATC_SIP_PORT} ${BATC_SIP_LOGIN} ${BATC_SIP_PASSWORD} ${BATC_SIP_AUTH_USER} ${BATC_SIP_FROM_USER}' \
        < /etc/asterisk/pjsip.batc.conf.tmpl > /etc/asterisk/pjsip.batc.conf
    echo "BATC trunk configured: $BATC_SIP_LOGIN@$BATC_SIP_DOMAIN:$BATC_SIP_PORT" >&2
else
    echo '; BATC trunk disabled: BATC_AGENT_LOGIN/BATC_AGENT_PASSWORD not set' \
        > /etc/asterisk/pjsip.batc.conf
    echo "BATC trunk disabled: credentials are missing" >&2
fi

exec asterisk -f -vvv
